import { test, expect } from '@playwright/test';

test.describe('JavaScript Alerts - Confirm Dialog', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/javascript_alerts');
  });

  test('should show "You clicked: Ok" when confirming the JS confirm dialog', async ({ page }) => {
    // Set up listener for the dialog and accept it
    page.once('dialog', dialog => {
      expect(dialog.type()).toBe('confirm');
      dialog.accept();
    });

    // Click the button that triggers the confirm dialog
    await page.getByRole('button', { name: 'Click for JS Confirm' }).click();

    // Verify the result shows "You clicked: Ok"
    const resultElement = page.locator('#result');
    await expect(resultElement).toContainText('You clicked: Ok');
  });

  test('should show "You clicked: Cancel" when dismissing the JS confirm dialog', async ({ page }) => {
    // Set up listener for the dialog and dismiss it
    page.once('dialog', dialog => {
      expect(dialog.type()).toBe('confirm');
      dialog.dismiss();
    });

    // Click the button that triggers the confirm dialog
    await page.getByRole('button', { name: 'Click for JS Confirm' }).click();

    // Verify the result shows "You clicked: Cancel"
    const resultElement = page.locator('#result');
    await expect(resultElement).toContainText('You clicked: Cancel');
  });

  test('should handle multiple confirm dialogs with different actions', async ({ page }) => {
    // First dialog - accept it
    page.once('dialog', dialog => {
      dialog.accept();
    });

    await page.getByRole('button', { name: 'Click for JS Confirm' }).click();
    await expect(page.locator('#result')).toContainText('You clicked: Ok');

    // Second dialog - dismiss it
    page.once('dialog', dialog => {
      dialog.dismiss();
    });

    await page.getByRole('button', { name: 'Click for JS Confirm' }).click();
    await expect(page.locator('#result')).toContainText('You clicked: Cancel');
  });
});
